import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { AnimatePresence, motion, useReducedMotion } from 'motion/react';
import { ArrowLeft, ArrowRight, Loader2, PackageOpen, Sparkles } from 'lucide-react';
import { supabase } from '../../lib/supabase';

type OAuthProvider = 'google' | 'azure';

type AuthProduct = {
  id: string;
  title: string;
  slug?: string | null;
  type?: string | null;
  category?: string | null;
  images?: string[] | string | null;
  image_url?: string | null;
  thumbnail?: string | null;
  price?: number | string | null;
  base_currency?: string | null;
};

type MobileAuthOnboardingProps = {
  screen: 'showcase' | 'choice';
  oauthProviderLoading: OAuthProvider | null;
  onBackHome: () => void;
  onBackToShowcase: () => void;
  onContinue: () => void;
  onLogin: () => void;
  onSignup: () => void;
  onGoogleLogin: () => void;
  onMicrosoftLogin: () => void;
};

const getProductImage = (product: AuthProduct) => {
  if (Array.isArray(product.images)) {
    const image = product.images.find((value) => typeof value === 'string' && value.trim());
    if (image) return image;
  }

  if (typeof product.images === 'string' && product.images.trim()) {
    try {
      const parsed = JSON.parse(product.images);
      if (Array.isArray(parsed)) {
        const image = parsed.find((value) => typeof value === 'string' && value.trim());
        if (image) return image;
      }
    } catch {
      return product.images;
    }
  }

  return product.image_url || product.thumbnail || null;
};

const formatPrice = (product: AuthProduct) => {
  const amount = Number(product.price || 0);
  if (!Number.isFinite(amount) || amount <= 0) return 'Free';

  const requestedCurrency = String(product.base_currency || 'EUR').toUpperCase();
  const currency = /^[A-Z]{3}$/.test(requestedCurrency) ? requestedCurrency : 'EUR';

  try {
    return new Intl.NumberFormat('en-GB', {
      style: 'currency',
      currency,
      maximumFractionDigits: amount % 1 === 0 ? 0 : 2,
    }).format(amount);
  } catch {
    return `${currency} ${amount.toFixed(amount % 1 === 0 ? 0 : 2)}`;
  }
};

const GoogleMark = () => (
  <svg className="h-5 w-5" viewBox="0 0 24 24" aria-hidden="true">
    <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z" fill="#4285F4" />
    <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853" />
    <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" fill="#FBBC05" />
    <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335" />
  </svg>
);

export const MobileAuthOnboarding = ({
  screen,
  oauthProviderLoading,
  onBackHome,
  onBackToShowcase,
  onContinue,
  onLogin,
  onSignup,
  onGoogleLogin,
  onMicrosoftLogin,
}: MobileAuthOnboardingProps) => {
  const reduceMotion = useReducedMotion();
  const [products, setProducts] = useState<AuthProduct[]>([]);
  const [productsState, setProductsState] = useState<'loading' | 'ready' | 'empty' | 'unavailable'>('loading');
  const [activeIndex, setActiveIndex] = useState(0);
  const [direction, setDirection] = useState(1);

  useEffect(() => {
    let cancelled = false;

    const loadProducts = async () => {
      const { data, error } = await supabase
        .from('listings')
        .select('id, title, slug, type, category, images, image_url, thumbnail, price, base_currency')
        .in('status', ['active', 'published'])
        .is('deleted_at', null)
        .or('is_sandbox.is.null,is_sandbox.eq.false')
        .order('published_at', { ascending: false, nullsFirst: false })
        .limit(24);

      if (cancelled) return;
      if (error) {
        console.error('[auth-product-showcase]', { code: error.code, status: error.details ? 'query_failed' : 'unavailable' });
        setProductsState('unavailable');
        return;
      }

      const realProducts = ((data || []).filter(
        (product) => product?.id && typeof product?.title === 'string' && product.title.trim(),
      ) as AuthProduct[])
        .sort((first, second) => Number(Boolean(getProductImage(second))) - Number(Boolean(getProductImage(first))))
        .slice(0, 8);
      setProducts(realProducts);
      setProductsState(realProducts.length ? 'ready' : 'empty');
    };

    void loadProducts();
    return () => {
      cancelled = true;
    };
  }, []);

  const moveSlider = useCallback((step: number) => {
    if (products.length < 2) return;
    setDirection(step);
    setActiveIndex((current) => (current + step + products.length) % products.length);
  }, [products.length]);

  useEffect(() => {
    if (screen !== 'showcase' || products.length < 2 || reduceMotion) return undefined;
    const timer = window.setInterval(() => moveSlider(1), 4_200);
    return () => window.clearInterval(timer);
  }, [moveSlider, products.length, reduceMotion, screen]);

  const activeProduct = products[activeIndex];
  const nextProduct = products.length > 1 ? products[(activeIndex + 1) % products.length] : null;
  const activeImage = activeProduct ? getProductImage(activeProduct) : null;
  const nextImage = nextProduct ? getProductImage(nextProduct) : null;
  const statusCopy = useMemo(() => {
    if (productsState === 'loading') return 'Loading Wersee products…';
    if (productsState === 'unavailable') return 'Products are temporarily unavailable.';
    return 'There are no public products to show yet.';
  }, [productsState]);

  return (
    <div className="relative min-h-[100dvh] overflow-hidden bg-[#050505] text-white lg:hidden">
      <div className="pointer-events-none absolute inset-0">
        <motion.div
          className="absolute -left-24 top-10 h-72 w-72 rounded-full bg-indigo-600/20 blur-[90px]"
          animate={reduceMotion ? undefined : { x: [0, 28, 0], y: [0, -18, 0], opacity: [0.55, 0.8, 0.55] }}
          transition={{ duration: 8, repeat: Infinity, ease: 'easeInOut' }}
        />
        <motion.div
          className="absolute -right-28 bottom-24 h-80 w-80 rounded-full bg-fuchsia-600/15 blur-[100px]"
          animate={reduceMotion ? undefined : { x: [0, -24, 0], y: [0, 22, 0], opacity: [0.45, 0.72, 0.45] }}
          transition={{ duration: 9, repeat: Infinity, ease: 'easeInOut' }}
        />
        <div className="absolute inset-0 bg-[url('/noise.svg')] opacity-[0.12] mix-blend-overlay" />
      </div>

      <AnimatePresence mode="wait" initial={false}>
        {screen === 'showcase' ? (
          <motion.section
            key="product-showcase"
            initial={{ opacity: 0, x: -24 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -28 }}
            transition={{ duration: reduceMotion ? 0 : 0.45, ease: [0.16, 1, 0.3, 1] }}
            className="relative z-10 flex min-h-[100dvh] flex-col px-5 pb-[calc(1rem+env(safe-area-inset-bottom))] pt-[calc(0.75rem+env(safe-area-inset-top))]"
          >
            <header className="flex min-h-12 items-center justify-between">
              <button
                type="button"
                onClick={onBackHome}
                className="flex min-h-11 min-w-11 items-center justify-center rounded-full border border-white/10 bg-black/30 text-white/70 backdrop-blur-xl transition active:scale-95"
                aria-label="Back to home"
              >
                <ArrowLeft className="h-5 w-5" />
              </button>
              <div className="flex items-center gap-2 rounded-full border border-white/10 bg-black/30 px-3 py-2 backdrop-blur-xl">
                <span className="h-2 w-2 rounded-full bg-emerald-400 shadow-[0_0_14px_rgba(52,211,153,0.8)]" />
                <span className="text-[10px] font-bold uppercase tracking-[0.18em] text-white/65">Live on Wersee</span>
              </div>
            </header>

            <div className="relative mt-4 min-h-0 flex-1">
              {productsState === 'ready' && activeProduct ? (
                <div className="relative h-full min-h-[390px]">
                  {nextProduct && (
                    <motion.div
                      aria-hidden="true"
                      className="absolute inset-x-5 bottom-3 top-9 overflow-hidden rounded-[2.2rem] border border-white/10 bg-white/[0.05]"
                      animate={{ rotate: 3, x: 16, scale: 0.94, opacity: 0.52 }}
                    >
                      {nextImage && <img src={nextImage} alt="" className="h-full w-full object-cover opacity-40" referrerPolicy="no-referrer" />}
                    </motion.div>
                  )}

                  <AnimatePresence mode="popLayout" custom={direction}>
                    <motion.article
                      key={activeProduct.id}
                      custom={direction}
                      initial={reduceMotion ? { opacity: 0 } : { opacity: 0, x: direction > 0 ? 90 : -90, rotate: direction > 0 ? 3 : -3, scale: 0.96 }}
                      animate={{ opacity: 1, x: 0, rotate: 0, scale: 1 }}
                      exit={reduceMotion ? { opacity: 0 } : { opacity: 0, x: direction > 0 ? -90 : 90, rotate: direction > 0 ? -3 : 3, scale: 0.96 }}
                      transition={{ duration: reduceMotion ? 0 : 0.5, ease: [0.16, 1, 0.3, 1] }}
                      drag={products.length > 1 ? 'x' : false}
                      dragConstraints={{ left: 0, right: 0 }}
                      dragElastic={0.16}
                      onDragEnd={(_, info) => {
                        if (Math.abs(info.offset.x) < 55) return;
                        moveSlider(info.offset.x < 0 ? 1 : -1);
                      }}
                      className="absolute inset-0 touch-pan-y overflow-hidden rounded-[2.2rem] border border-white/15 bg-[#111] shadow-[0_30px_90px_rgba(0,0,0,0.65)]"
                    >
                      {activeImage ? (
                        <img
                          src={activeImage}
                          alt=""
                          className="h-full w-full select-none object-cover"
                          draggable={false}
                          referrerPolicy="no-referrer"
                        />
                      ) : (
                        <div className="relative flex h-full w-full items-center justify-center overflow-hidden bg-gradient-to-br from-indigo-950 via-[#111] to-fuchsia-950">
                          <div className="absolute -left-14 top-12 h-48 w-48 rounded-full border border-white/10" />
                          <div className="absolute -right-20 top-36 h-64 w-64 rounded-full border border-white/[0.07]" />
                          <div className="absolute inset-x-6 top-1/2 h-px bg-gradient-to-r from-transparent via-white/15 to-transparent" />
                          <div className="relative flex flex-col items-center gap-4 text-center">
                            <PackageOpen className="h-14 w-14 text-white/24" />
                            <span className="max-w-[15rem] text-[11px] font-black uppercase tracking-[0.28em] text-white/22">
                              {activeProduct.category || activeProduct.type || 'Wersee'}
                            </span>
                          </div>
                        </div>
                      )}
                      <div className="absolute inset-0 bg-gradient-to-b from-black/5 via-transparent to-black/95" />
                      <div className="absolute inset-x-0 bottom-0 p-6">
                        <div className="mb-3 flex items-center gap-2">
                          <span className="rounded-full border border-white/15 bg-black/45 px-3 py-1.5 text-[10px] font-bold uppercase tracking-[0.16em] text-white/75 backdrop-blur-lg">
                            {activeProduct.category || activeProduct.type || 'Wersee product'}
                          </span>
                          <span className="rounded-full bg-white px-3 py-1.5 text-[11px] font-black text-black">
                            {formatPrice(activeProduct)}
                          </span>
                        </div>
                        <h2 className="line-clamp-2 max-w-[90%] text-3xl font-black leading-[1.05] tracking-[-0.04em]">
                          {activeProduct.title}
                        </h2>
                      </div>
                    </motion.article>
                  </AnimatePresence>
                </div>
              ) : (
                <div className="flex h-full min-h-[390px] items-center justify-center rounded-[2.2rem] border border-white/10 bg-white/[0.035] px-8 text-center backdrop-blur-xl">
                  <div className="space-y-4">
                    {productsState === 'loading' ? (
                      <Loader2 className="mx-auto h-9 w-9 animate-spin text-white/45" />
                    ) : (
                      <PackageOpen className="mx-auto h-10 w-10 text-white/30" />
                    )}
                    <p className="text-sm font-medium text-white/50">{statusCopy}</p>
                  </div>
                </div>
              )}
            </div>

            <div className="pt-5">
              {products.length > 1 && (
                <div className="mb-4 flex justify-center gap-1.5" aria-label="Product carousel">
                  {products.map((product, index) => (
                    <button
                      key={product.id}
                      type="button"
                      onClick={() => {
                        setDirection(index > activeIndex ? 1 : -1);
                        setActiveIndex(index);
                      }}
                      className={`h-1.5 rounded-full transition-all ${index === activeIndex ? 'w-7 bg-white' : 'w-1.5 bg-white/25'}`}
                      aria-label={`Show product ${index + 1}`}
                      aria-current={index === activeIndex ? 'true' : undefined}
                    />
                  ))}
                </div>
              )}
              <div className="mb-5 text-center">
                <h1 className="text-[2rem] font-black leading-none tracking-[-0.045em]">Discover. Create. Sell.</h1>
                <p className="mx-auto mt-2 max-w-xs text-sm leading-relaxed text-white/48">
                  One account for products, creators, and everything you build on Wersee.
                </p>
              </div>
              <button
                type="button"
                onClick={onContinue}
                className="group flex min-h-14 w-full items-center justify-center gap-2 rounded-2xl bg-white px-5 text-base font-black text-black shadow-[0_16px_45px_rgba(255,255,255,0.12)] transition active:scale-[0.98]"
              >
                Get started
                <ArrowRight className="h-5 w-5 transition-transform group-active:translate-x-1" />
              </button>
            </div>
          </motion.section>
        ) : (
          <motion.section
            key="auth-choice"
            initial={{ opacity: 0, x: 28 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: 24 }}
            transition={{ duration: reduceMotion ? 0 : 0.45, ease: [0.16, 1, 0.3, 1] }}
            className="relative z-10 flex min-h-[100dvh] flex-col px-5 pb-[calc(1.5rem+env(safe-area-inset-bottom))] pt-[calc(0.75rem+env(safe-area-inset-top))]"
          >
            <header className="flex min-h-12 items-center">
              <button
                type="button"
                onClick={onBackToShowcase}
                className="flex min-h-11 min-w-11 items-center justify-center rounded-full border border-white/10 bg-white/[0.04] text-white/70 transition active:scale-95"
                aria-label="Back to products"
              >
                <ArrowLeft className="h-5 w-5" />
              </button>
            </header>

            <div className="flex flex-1 flex-col justify-center py-8">
              <motion.div
                initial={reduceMotion ? undefined : { opacity: 0, y: 16, scale: 0.95 }}
                animate={{ opacity: 1, y: 0, scale: 1 }}
                transition={{ delay: reduceMotion ? 0 : 0.12 }}
                className="mb-8"
              >
                <div className="mb-6 flex h-16 w-16 items-center justify-center rounded-[1.4rem] border border-white/10 bg-gradient-to-br from-indigo-500/25 to-fuchsia-500/15 shadow-[0_20px_60px_rgba(99,102,241,0.22)]">
                  <Sparkles className="h-7 w-7 text-indigo-200" />
                </div>
                <p className="mb-3 text-[11px] font-black uppercase tracking-[0.22em] text-indigo-300">Welcome to Wersee</p>
                <h1 className="text-[2.65rem] font-black leading-[0.98] tracking-[-0.055em]">How would you like to start?</h1>
                <p className="mt-4 max-w-sm text-base leading-relaxed text-white/50">
                  Sign in to your account or create one for free.
                </p>
              </motion.div>

              <div className="space-y-3">
                <button
                  type="button"
                  onClick={onSignup}
                  className="group flex min-h-14 w-full items-center justify-between rounded-2xl bg-white px-5 text-base font-black text-black transition active:scale-[0.98]"
                >
                  Create account
                  <ArrowRight className="h-5 w-5 transition-transform group-active:translate-x-1" />
                </button>
                <button
                  type="button"
                  onClick={onLogin}
                  className="flex min-h-14 w-full items-center justify-center rounded-2xl border border-white/12 bg-white/[0.055] px-5 text-base font-bold text-white backdrop-blur-xl transition active:scale-[0.98] active:bg-white/10"
                >
                  Sign in
                </button>
              </div>

              <div className="my-6 flex items-center gap-4">
                <span className="h-px flex-1 bg-white/8" />
                <span className="text-[10px] font-bold uppercase tracking-[0.18em] text-white/30">or continue with</span>
                <span className="h-px flex-1 bg-white/8" />
              </div>

              <div className="grid grid-cols-2 gap-3">
                <button
                  type="button"
                  onClick={onGoogleLogin}
                  disabled={Boolean(oauthProviderLoading)}
                  className="flex min-h-14 items-center justify-center gap-2.5 rounded-2xl border border-white/10 bg-white/[0.045] font-bold text-white transition active:scale-[0.98] disabled:opacity-50"
                >
                  {oauthProviderLoading === 'google' ? <Loader2 className="h-5 w-5 animate-spin" /> : <GoogleMark />}
                  Google
                </button>
                <button
                  type="button"
                  onClick={onMicrosoftLogin}
                  disabled={Boolean(oauthProviderLoading)}
                  className="flex min-h-14 items-center justify-center gap-2.5 rounded-2xl border border-white/10 bg-white/[0.045] font-bold text-white transition active:scale-[0.98] disabled:opacity-50"
                >
                  {oauthProviderLoading === 'azure' ? (
                    <Loader2 className="h-5 w-5 animate-spin" />
                  ) : (
                    <img src="/brand/microsoft-logo.webp" alt="" aria-hidden="true" className="h-5 w-5 object-contain" />
                  )}
                  Microsoft
                </button>
              </div>
            </div>

            <p className="text-center text-xs leading-relaxed text-white/30">
              By continuing, you agree to Wersee&apos;s Terms and Privacy Policy.
            </p>
          </motion.section>
        )}
      </AnimatePresence>
    </div>
  );
};
